#include <Wire.h>
#include <WiFi.h>
#include <WebServer.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_BME280.h>

// Wi-Fi credentials - edit before flashing
const char* WIFI_SSID = "YOUR_SSID";
const char* WIFI_PASS = "YOUR_PASSWORD";

// Wiring (see device graph): BME280 + OLED share SDA/SCL (XIAO default I2C pins),
// status LED on D10 via 1k, page button on D1 (INPUT_PULLUP, LOW = pressed)
#define LED_PIN D10
#define BTN_PIN D1
#define SCREEN_W 128
#define SCREEN_H 64

Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);
Adafruit_BME280 bme;
WebServer server(80);

bool bmeOK = false;
bool dispOK = false;
int page = 0;
unsigned long lastRead = 0;
float tC = 0, hPct = 0, pHPa = 0;
unsigned long lastBtn = 0;
bool lastBtnState = HIGH;

void showPage() {
  if (!dispOK) return;
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  if (!bmeOK) {
    display.println("BME280 missing");
    display.println("check wiring");
  } else if (page == 0) {
    display.println("HOME WEATHER");
    display.print("Temp: "); display.print(tC, 1); display.println(" C");
    display.print("Hum : "); display.print(hPct, 0); display.println(" %");
    display.print("Pres: "); display.print(pHPa, 0); display.println(" hPa");
  } else {
    display.println("WIFI / INFO");
    display.print("IP: "); display.println(WiFi.localIP().toString());
    display.print("Temp: "); display.print(tC, 1); display.println(" C");
    display.println("press btn: page");
  }
  display.display();
}

void handleRoot() {
  String h = "<html><body><h1>Home Weather</h1>";
  if (!bmeOK) h += "<p>sensor missing</p>";
  else {
    h += "<p>Temperature: " + String(tC, 1) + " C</p>";
    h += "<p>Humidity: " + String(hPct, 0) + " %</p>";
    h += "<p>Pressure: " + String(pHPa, 0) + " hPa</p>";
  }
  h += "</body></html>";
  server.send(200, "text/html", h);
}

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  pinMode(BTN_PIN, INPUT_PULLUP);
  Serial.begin(115200);
  Wire.begin(); // module default SDA/SCL pins
  bmeOK = bme.begin(0x76);
  if (!bmeOK) bmeOK = bme.begin(0x77);
  dispOK = display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  if (dispOK) { display.clearDisplay(); display.display(); }
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  unsigned long t0 = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 15000) delay(250);
  server.on("/", handleRoot);
  server.begin();
  showPage();
}

void loop() {
  // button with 50 ms debounce, acts on press edge
  bool s = digitalRead(BTN_PIN);
  if (s != lastBtnState && millis() - lastBtn > 50) {
    lastBtn = millis();
    if (s == LOW) { page = (page + 1) % 2; showPage(); }
    lastBtnState = s;
  }
  // read sensor every 2 s (BME280: no faster than ~1 Hz needed)
  if (millis() - lastRead > 2000) {
    lastRead = millis();
    if (bmeOK) {
      tC = bme.readTemperature();
      hPct = bme.readHumidity();
      pHPa = bme.readPressure() / 100.0;
      if (isnan(tC) || isnan(hPct)) { /* keep old values on failed read */ }
      // R4: blink status LED on every reading
      digitalWrite(LED_PIN, HIGH); delay(60); digitalWrite(LED_PIN, LOW);
      showPage();
    }
  }
  server.handleClient();
  delay(5);
}

